    // Handle form submission
    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const selectedValue = document.querySelector(
            'input[name="notification-preference"]:checked'
        );

        if (selectedValue) {
            const value = selectedValue.value;
            const displayText = selectedValue.closest('.radio-label').querySelector('.radio-text').textContent;

            // Store preference (could be sent to a server)
            console.log(`Notification preference saved: ${displayText}`);

            // Show feedback
            showSuccessMessage(displayText);

            // Optional: Reset form after a delay
            setTimeout(() => {
                form.reset();
                clearSuccessMessage();
            }, 2000);
        }
    });

    // Handle radio input changes
    radioInputs.forEach((input) => {
        input.addEventListener('change', () => {
            // Clear any success message when user changes selection
            clearSuccessMessage();
        });
    });

    function showSuccessMessage(preference) {
        // Remove existing message if any
        clearSuccessMessage();

        const message = document.createElement('div');
        message.className = 'success-message';
        message.textContent = `✓ Preference saved: ${preference}`;
        form.insertAdjacentElement('afterend', message);
    }

    function clearSuccessMessage() {
        const existingMessage = document.querySelector('.success-message');
        if (existingMessage) {
            existingMessage.remove();
        }
    }
});
